#include <iostream>
using namespace std;

// 直接插入排序: R[1..n], R[0]暂存兼作哨兵
void InsertSort(int* R, int n) {
    for (int i = 2; i <= n; i++) {
        R[0] = R[i];
        int j = i - 1;
        while (R[j] > R[0]) { R[j+1] = R[j]; j--; }  // 后移
        R[j+1] = R[0];
    }
}  // 时间: 平均O(n²), 最好O(n); 稳定

// 折半插入排序: 用折半查找找插入位置
void BInsertSort(int* R, int n) {
    for (int i = 2; i <= n; i++) {
        R[0] = R[i];
        int low = 1, high = i - 1;
        while (low <= high) {  // 折半查找
            int mid = (low + high) / 2;
            if (R[mid] > R[0]) high = mid - 1;
            else low = mid + 1;
        }
        for (int j = i - 1; j >= low; j--) R[j+1] = R[j];  // 后移
        R[low] = R[0];
    }
}  // 比较O(n log n), 移动O(n²); 稳定

// 冒泡排序: 有flag标志检测是否已有序
void BubbleSort(int* R, int n) {
    bool flag = true;
    for (int i = 1; i < n && flag; i++) {
        flag = false;
        for (int j = 1; j <= n - i; j++)
            if (R[j] > R[j+1]) { swap(R[j], R[j+1]); flag = true; }
    }
}  // 最好O(n), 平均/最坏O(n²); 稳定

// 快速排序: 分治法, Partition选第一个记录为枢轴
int Partition(int* R, int low, int high) {
    R[0] = R[low]; int pivot = R[0];
    while (low < high) {
        while (low < high && R[high] >= pivot) high--;
        R[low] = R[high];
        while (low < high && R[low] <= pivot) low++;
        R[high] = R[low];
    }
    R[low] = R[0];
    return low;
}

void QSort(int* R, int low, int high) {
    if (low < high) {
        int pivotloc = Partition(R, low, high);
        QSort(R, low, pivotloc - 1);
        QSort(R, pivotloc + 1, high);
    }
}  // 平均O(n log n), 最坏O(n²); 不稳定; 空间O(log n)递归栈

// 快速排序优化: 三者取中选枢轴 + 小范围用插入排序

#include <iostream>
using namespace std;

// 简单选择排序
void SelectSort(int* R, int n) {
    for (int i = 1; i < n; i++) {
        int min = i;
        for (int j = i+1; j <= n; j++)
            if (R[j] < R[min]) min = j;
        if (min != i) swap(R[i], R[min]);
    }
}  // O(n²); 不稳定

// 堆排序（大根堆）
void HeapAdjust(int* R, int s, int m) {
    int rc = R[s];
    for (int j = 2*s; j <= m; j *= 2) {
        if (j < m && R[j] < R[j+1]) j++;  // 选择较大孩子
        if (rc >= R[j]) break;
        R[s] = R[j]; s = j;
    }
    R[s] = rc;
}

void HeapSort(int* R, int n) {
    for (int i = n/2; i > 0; i--)  // 建初堆
        HeapAdjust(R, i, n);
    for (int i = n; i > 1; i--) {  // 排序
        swap(R[1], R[i]);
        HeapAdjust(R, 1, i-1);
    }
}  // O(n log n); 不稳定; 原地排序

// 归并排序
void Merge(int* R, int low, int mid, int high) {
    int* T = new int[high - low + 1];
    int i = low, j = mid + 1, k = 0;
    while (i <= mid && j <= high)  // 归并
        T[k++] = (R[i] <= R[j]) ? R[i++] : R[j++];
    while (i <= mid) T[k++] = R[i++];    // 剩余
    while (j <= high) T[k++] = R[j++];
    for (k = 0; low <= high; ) R[low++] = T[k++];
    delete[] T;
}

void MSort(int* R, int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2;
        MSort(R, low, mid);
        MSort(R, mid+1, high);
        Merge(R, low, mid, high);
    }
}  // O(n log n); 稳定; 空间O(n)

// 希尔排序
void ShellSort(int* R, int n) {
    for (int d = n/2; d >= 1; d /= 2)  // 增量序列
        for (int i = d+1; i <= n; i++) {
            R[0] = R[i]; int j = i - d;
            while (j > 0 && R[j] > R[0]) { R[j+d] = R[j]; j -= d; }
            R[j+d] = R[0];
        }
}  // 约O(n^1.3); 不稳定
